pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public {
        // Ensure the sender is the depositor account for the reference behavior
        vm.prank(0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001);
        try c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ) returns (bool ok) {
            // If the call succeeded, the timestamp must equal _timestamp
            assertEq(c.timestamp(), _timestamp);
        } catch {
            // In the reference version, the call should always succeed from the depositor.
            // In the buggy version, it will revert. We assert that if it reverted,
            // the timestamp remains 0 (its default), which differs from _timestamp
            // if _timestamp != 0, thus the bug is exposed.
            assertEq(c.timestamp(), 0);
        }
    }
}

